shell_commands:
/bin/zsh -lc "python3 - <<'PY'
p='specs/hal-engine-tool-input-validation/spec.md'
s=open(p).read().replace('coercing types or applying defaults.','coercing types or applying defaults ([validated by: passes valid input and extra properties unchanged specs/hal-engine-tool-input-validation/spec.md#3](../../src/orchestration/tools/registry.passthrough.test.ts#L5)).')
open(p,'w').write(s)
PY
cat > src/orchestration/tools/registry.passthrough.test.ts <<'EOF'
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry valid input', () => {
  it('passes valid input and extra properties unchanged specs/hal-engine-tool-input-validation/spec.md#3', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async (_input: Record<string, unknown>) => 'ok');
    registry.register({name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}}, execute);
    const input = {location: 'Berlin', extra: 42};
    await registry.execute('weather', input);
    expect(execute).toHaveBeenCalledTimes(1);
    expect(execute.mock.calls[0][0]).toEqual(input);
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.passthrough.test.ts"
